import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"遭厄","description":"","frontmatter":{"title":"遭厄","date":"2026-11-24T00:00:00.000Z","seq":61,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"王逸","source_book":"楚辞","prev":{"text":"悯上","link":"/blogs/楚辞/悯上.html"},"next":{"text":"悼乱","link":"/blogs/楚辞/悼乱.html"}},"headers":[],"relativePath":"blogs/楚辞/遭厄.md","filePath":"blogs/楚辞/遭厄.md"}'),o={name:"blogs/楚辞/遭厄.md"};function l(n,a,c,m,r,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="遭厄" tabindex="-1">遭厄 <a class="header-anchor" href="#遭厄" aria-label="Permalink to &quot;遭厄&quot;">​</a></h1><p class="poem-meta">先秦 · 王逸　·　九思</p><div class="poem"><p class="poem-stanza">悼屈子兮遭厄，沉王躬兮湘汨。</p><p class="poem-stanza">何楚国兮难化，迄于今兮不易。</p><p class="poem-stanza">士莫志兮羔裘，竞佞谀兮谗阋。</p><p class="poem-stanza">指正义兮为曲，訿玉璧兮为石。</p><p class="poem-stanza">殦雕游兮华屋，鵔鸃栖兮柴蔟。</p><p class="poem-stanza">起奋迅兮奔走，违群小兮謑訽。</p><p class="poem-stanza">载青云兮上昇，適昭明兮所处。</p><p class="poem-stanza">蹑天衢兮长驱，踵九阳兮戏荡。</p><p class="poem-stanza">越云汉兮南济，秣余马兮河鼓。</p><p class="poem-stanza">云霓纷兮晻翳，参辰回兮颠倒。</p><p class="poem-stanza">逢流星兮问路，顾我指兮从左。</p><p class="poem-stanza">俓娵觜兮直驰，御者迷兮失轨。</p><p class="poem-stanza">遂踢达兮邪造，与日月兮殊道。</p><p class="poem-stanza">志阏绝兮安如，哀所求兮不耦。</p><p class="poem-stanza">攀天阶兮下视，见鄢郢兮旧宇。</p><p class="poem-stanza">意逍遥兮欲归，众秽盛兮沓沓。</p><p class="poem-stanza">思哽饐兮诘诎，涕流澜兮如雨。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
